// 神奇的魔法：将元组的值转化为对象的键 🔑
type TupleToObject<T extends readonly any[]> = {
  [K in T[number]]: K
}

// 具体表现是这样的 👇
const tuple = ['tesla', 'model 3', 'model X', 'model Y'] as const;
type Result = TupleToObject<typeof tuple>;
/*
  Result 变成了：
  {
    'tesla': 'tesla';
    'model 3': 'model 3';
    'model X': 'model X';
    'model Y': 'model Y';
  }
*/
